// Amdahl's Law and Gustafson's Law modelled in JavaScript

// --- Amdahl's Law ---
// parallelFraction: 0.0 to 1.0 (the portion that can run in parallel)
function amdahlSpeedup(parallelFraction, numCores) {
  const sequential = 1 - parallelFraction;
  return 1 / (sequential + parallelFraction / numCores);
}

const p = 0.9; // 90% parallelisable, 10% must be serial
console.log('=== Amdahl (fixed p=0.9) ===');
for (const n of [1, 2, 4, 8, 16, 32, 64, 1e9]) {
  const label = n >= 1e9 ? '∞' : String(n).padStart(2);
  console.log(`Cores: ${label}  Speedup: ${amdahlSpeedup(p, n).toFixed(2)}x`);
}
// Cores:  1  Speedup: 1.00x
// Cores:  2  Speedup: 1.82x
// Cores:  4  Speedup: 3.08x
// Cores:  8  Speedup: 4.71x
// Cores: 16  Speedup: 6.40x
// Cores: 64  Speedup: 8.77x
// Cores:  ∞  Speedup: 10.00x  ← hard ceiling at 1/(1-0.9)

// --- Gustafson's Law ---
// As problem size scales with cores, the parallelisable fraction grows
// scaledSpeedup ≈ N - serialFraction * (N - 1)
function gustafsonsSpeedup(serialFraction, numCores) {
  return numCores - serialFraction * (numCores - 1);
}

const s = 0.1; // 10% serial (same as above)
console.log('\n=== Gustafson (scaled workload, s=0.1) ===');
for (const n of [1, 2, 4, 8, 16, 32, 64]) {
  console.log(`Cores: ${String(n).padStart(2)}  Speedup: ${gustafsonsSpeedup(s, n).toFixed(2)}x`);
}
// Cores:  1  Speedup: 1.00x
// Cores:  2  Speedup: 1.90x
// Cores:  4  Speedup: 3.70x
// Cores:  8  Speedup: 7.30x
// Cores: 64  Speedup: 57.30x  ← near-linear scaling with scaled workload

// Side-by-side: concurrency for I/O-bound vs parallelism for CPU-bound
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');

if (isMainThread) {
  const CORES = os.cpus().length;
  console.log(`System cores: ${CORES}`);

  // ── I/O-BOUND: concurrency with async (one thread, many in-flight tasks) ──
  async function simulateNetworkRequest(id) {
    // In production: await fetch(url) or db.query(sql)
    await new Promise(resolve => setTimeout(resolve, 100)); // 100ms latency
    return `Request ${id} completed`;
  }

  async function runIOBound() {
    const start = Date.now();
    // Fire 20 requests concurrently — all 20 are in-flight simultaneously
    // Total time ≈ 100ms (not 20 × 100ms = 2000ms)
    const results = await Promise.all(
      Array.from({ length: 20 }, (_, i) => simulateNetworkRequest(i))
    );
    console.log(`I/O-bound: ${results.length} requests in ${Date.now() - start}ms`);
    // → ~100ms regardless of request count (up to the event loop limit)
  }

  // ── CPU-BOUND: parallelism with workers (one worker per core) ──
  function runCPUBound() {
    const start = Date.now();
    // Spin up CORES workers — each runs on its own OS thread
    const promises = Array.from({ length: CORES }, (_, i) =>
      new Promise((resolve, reject) => {
        const worker = new Worker(__filename, {
          workerData: { chunk: i, totalChunks: CORES }
        });
        worker.on('message', resolve);
        worker.on('error', reject);
      })
    );
    Promise.all(promises).then(results => {
      const total = results.reduce((s, r) => s + r.partialSum, 0);
      console.log(`CPU-bound: sum=${total} in ${Date.now() - start}ms using ${CORES} workers`);
    });
  }

  runIOBound().then(runCPUBound);

} else {
  // Worker thread: performs CPU-intensive summation on its assigned slice
  const { chunk, totalChunks } = workerData;
  const N = 50_000_000; // 50 million iterations split across workers
  const start = Math.floor((N / totalChunks) * chunk);
  const end   = Math.floor((N / totalChunks) * (chunk + 1));
  let partialSum = 0;
  for (let i = start; i < end; i++) partialSum += i;
  parentPort.postMessage({ chunk, partialSum });
}
